use std::path::Path;
use molten::coordination_delivery::*;
use molten::core_api::coordination_delivery::*;
use molten::core_api::fabric_time::*;

fn reference(c: char) -> String { format!("blake3:{}", c.to_string().repeat(64)) }
fn policy() -> DeliveryPolicy {
    DeliveryPolicy {
        schema: DELIVERY_POLICY_SCHEMA.into(), policy_id: "delivery-policy-v1".into(),
        visibility_timeout_ticks: 10, maximum_attempts: 2, retry_base_delay_ticks: 5,
        retry_maximum_delay_ticks: 5, retry_backoff: DeliveryBackoff::Fixed,
        ordering: DeliveryOrdering::StrictFifo, dead_letter_queue_id: "queue:delivery-dlq".into(),
        dead_letter_retention_ticks: 20, ready_capacity: 8, in_flight_capacity: 8,
        retry_capacity: 8, dead_letter_capacity: 8, metadata_byte_limit: 32, status_item_limit: 8,
        completion_authority_ref: reference('a'), expiry_authority_ref: reference('b'),
        redrive_authority_ref: reference('c'), retention_authority_ref: reference('d'),
        retryable_failure_classes: ["transient".into()].into_iter().collect(),
        poison_failure_classes: ["poison".into()].into_iter().collect(),
        poison_item_handling: PoisonItemHandling::DeadLetter, non_claims: required_delivery_non_claims(),
    }
}
fn manifest(p: &DeliveryPolicy) -> DeliveryManifest {
    DeliveryManifest {
        schema: DELIVERY_MANIFEST_SCHEMA.into(), extension_id: "coordination-delivery".into(),
        service_id: "coordination-delivery-local".into(), service_generation: 7,
        implementation_ref: reference('e'), time_profile_ref: reference('f'), policy_ref: identify_delivery_policy(p),
        port_bindings: REQUIRED_DELIVERY_PORTS.into_iter().enumerate().map(|(i, port)|
            (port.into(), reference(['1','2','3','4','5'][i]))).collect(),
        non_claims: required_delivery_non_claims(),
    }
}
fn time_profile(m: &DeliveryManifest) -> AdmittedTimeProfile {
    AdmittedTimeProfile {
        profile_id: "delivery-logical-time".into(), profile_ref: m.time_profile_ref.clone(),
        kind: TimeProfileKind::DeterministicSimulation, supported_domains: vec![TimeDomain::Logical],
        max_duration_ticks: MAX_DELIVERY_TICKS, max_uncertainty_ticks: 0, max_timers: 8,
        max_runnables: 8, max_entropy_request_bytes: 1, max_entropy_total_bytes: 1,
        max_scheduler_concurrency: 8, max_scheduler_queue_depth: 8, fairness_bound_turns: Some(MAX_DELIVERY_TICKS),
        scheduler_policy: SchedulerPolicy { ordering: SchedulerOrdering::Fifo,
            replay: SchedulerReplayPolicy::Deterministic, overload: SchedulerOverloadPolicy::Reject },
        evidence_mode: TimeEvidenceMode::SelectedSemanticBoundaries, non_claims: REQUIRED_TIME_NON_CLAIMS.to_vec(),
    }
}
fn request(m: &DeliveryManifest, queue: &str, id: char, tick: u64, operation: DeliveryOperation) -> DeliveryRequest {
    DeliveryRequest { schema: DELIVERY_REQUEST_SCHEMA.into(), queue_id: queue.into(), operation_id: reference(id),
        actor_id: "consumer-a".into(), service_generation: 7, consistency_epoch: 11, engine_epoch: 13,
        time_profile_ref: m.time_profile_ref.clone(), logical_tick: tick, currentness: DeliveryCurrentness::Linearizable,
        authority_refs: vec![reference('6')], policy_refs: vec![m.policy_ref.clone()],
        resource_refs: vec![reference('7')], evidence_refs: vec![reference('8')], operation }
}
fn enqueue(m: &DeliveryManifest, queue: &str) -> DeliveryRequest {
    request(m, queue, '1', 100, DeliveryOperation::Enqueue {
        item_ref: reference('a'), content_ref: reference('9'), metadata_ref: reference('0'), metadata_bytes: 32 })
}
struct ObservedStore { inner: Local, commits: usize }
impl DeliveryCommitPort for ObservedStore {
    fn load(&self, queue: &str) -> PortResult<Option<PublishedState>> { self.inner.load(queue) }
    fn compare_and_commit(&mut self, r: &CommitRequest) -> PortResult<CommitObservation> {
        self.commits += 1;
        self.inner.compare_and_commit(r)
    }
}
#[derive(Default)]
struct Timers { observed: Vec<DeliveryTimerIntent> }
impl DeliveryTimerPort for Timers {
    fn apply_timer_intents(&mut self, intents: &[DeliveryTimerIntent]) -> PortResult<TimerObservation> {
        self.observed.extend_from_slice(intents);
        Ok(TimerObservation { accepted_timer_refs: intents.iter().map(|i| i.timer_id.clone()).collect(),
            failed_timer_refs: vec![], outcome_unknown: false })
    }
}
#[derive(Default)]
struct Statuses { observed: Vec<DeliveryStatus> }
impl DeliveryStatusPort for Statuses {
    fn publish_status(&mut self, status: &DeliveryStatus) -> PortResult<StatusObservation> {
        self.observed.push(status.clone());
        Ok(StatusObservation { published_status_ref: Some(identify_canonical_status(status).expect("status identity")),
            outcome_unknown: false })
    }
}
struct Context { manifest: DeliveryManifest, policy: DeliveryPolicy, time: AdmittedTimeProfile, host: BindingFacts }
impl Context {
    fn new() -> Self {
        let policy = policy(); let manifest = manifest(&policy); let time = time_profile(&manifest);
        let host = BindingFacts { schema: DELIVERY_HOST_BINDING_SCHEMA.into(), system_extension_manifest_ref: reference('9'),
            extension_id: manifest.extension_id.clone(), service_id: manifest.service_id.clone(), service_generation: 7,
            lifecycle_running: true, port_bindings: manifest.port_bindings.clone() };
        Self { manifest, policy, time, host }
    }
}
fn invoke(label: &str, c: &Context, store: &mut ObservedStore, timers: &mut Timers, statuses: &mut Statuses,
          r: &DeliveryRequest, output: &Path) -> Outcome {
    let before = store.load(&r.queue_id).expect("load before");
    let commits = store.commits; let prior_timers = timers.observed.clone(); let prior_statuses = statuses.observed.clone();
    let expected = before.as_ref().map_or(ExpectedState { state_ref: None, revision: 0 },
        |s| ExpectedState { state_ref: Some(s.state_ref.clone()), revision: s.revision });
    let outcome = apply_request(store, timers, statuses, &Request { manifest: &c.manifest, policy: &c.policy,
        time_profile: &c.time, host_binding: &c.host, expected, request: r }).expect("real public delivery service");
    let parsed = molten::preserves_rail::parse_canonical_bytes(&outcome.receipt.bytes).expect("canonical receipt");
    assert_eq!(parsed, outcome.receipt.value);
    assert_eq!(molten::preserves_rail::canonical_bytes(&parsed).expect("canonical roundtrip"), outcome.receipt.bytes);
    assert!(!outcome.transition.worker_dispatch_authorized);
    assert!(!outcome.transition.external_effect_exactly_once);
    if outcome.transition.decision != DeliveryDecisionKind::Applied {
        assert_eq!(store.load(&r.queue_id).expect("load after"), before, "durable no-mutation: {label}");
        assert_eq!(store.commits, commits, "no compare-and-commit: {label}");
        assert_eq!(timers.observed, prior_timers, "no timer effects: {label}");
        assert_eq!(statuses.observed, prior_statuses, "no status effects: {label}");
        let published = before.as_ref().expect("all no-commit controls have prior state");
        assert_eq!(outcome.transition.next_state, published.state);
        assert_eq!(outcome.transition.before_state_ref, published.state_ref);
        assert_eq!(outcome.transition.after_state_ref, published.state_ref);
        assert!(outcome.commit_observation.is_none()); assert!(outcome.transition.timer_intents.is_empty());
        assert_eq!(outcome.timer_observation, TimerObservation::empty());
        assert_eq!(outcome.status_observation.published_status_ref, None);
    } else {
        assert_eq!(store.commits, commits + 1);
        assert_eq!(outcome.receipt.status, ServiceStatus::Applied);
    }
    std::fs::write(output.join(format!("{label}.preserves")), &outcome.receipt.bytes).expect("persist actual canonical receipt");
    println!("case={label} status={:?} issue={:?} revision={} commits={} token={} operation={} receipt={}",
        outcome.receipt.status, outcome.transition.issue, outcome.transition.next_state.revision, store.commits,
        outcome.transition.token.as_ref().map_or("none", |t| t.token_ref.as_str()),
        outcome.transition.operation_ref, outcome.receipt.receipt_ref);
    outcome
}
fn replay_identity(outcome: &Outcome, original: &Outcome, token: Option<&DeliveryToken>) {
    assert_eq!(outcome.receipt.status, ServiceStatus::DuplicateReplay);
    assert_eq!(outcome.transition.operation_ref, original.transition.operation_ref);
    assert_eq!(outcome.transition.prior_operation_ref.as_ref(), Some(&original.transition.operation_ref));
    assert_eq!(outcome.transition.token.as_ref(), token);
    assert!(molten::preserves_rail::contains_structural_content_ref(&outcome.receipt.value,
        &original.transition.operation_ref).expect("canonical original operation binding"));
}
fn main() -> std::process::ExitCode {
    let args = std::env::args().collect::<Vec<_>>();
    let state = Path::new(&args[1]); let output = Path::new(&args[2]);
    std::fs::create_dir_all(state).expect("owned state"); std::fs::create_dir_all(output).expect("owned evidence");
    let root = molten::node_state::DirectoryRoot::open(state).expect("capability root");
    root.create_layout().expect("layout");
    let storage = root.namespace(molten::node_state::NamespaceKind::Storage).expect("storage namespace");
    let c = Context::new(); let q = "queue:delivery";
    let mut store = ObservedStore { inner: Local::open(&storage, 13).expect("real Redb adapter"), commits: 0 };
    let mut timers = Timers::default(); let mut statuses = Statuses::default();
    let enqueue = enqueue(&c.manifest, q);
    invoke("enqueue", &c, &mut store, &mut timers, &mut statuses, &enqueue, output);
    let claim = request(&c.manifest, q, '2', 100, DeliveryOperation::Claim);
    let claimed = invoke("claim-a", &c, &mut store, &mut timers, &mut statuses, &claim, output);
    let token_a = claimed.transition.token.clone().expect("A token"); assert_eq!(token_a.consumer_id, "consumer-a");
    assert_eq!(token_a.visibility_deadline_tick, 110);
    let immediate = invoke("immediate-replay", &c, &mut store, &mut timers, &mut statuses, &claim, output);
    replay_identity(&immediate, &claimed, Some(&token_a));
    let enqueue_replay = invoke("enqueue-replay", &c, &mut store, &mut timers, &mut statuses, &enqueue, output);
    assert_eq!(enqueue_replay.transition.token, None);
    let mut conflict = claim.clone(); conflict.actor_id = "consumer-b".into();
    let mut wrong = request(&c.manifest, q, '5', 101, DeliveryOperation::Acknowledge { token: token_a.clone() });
    wrong.actor_id = "consumer-b".into();
    let mut stale_token = token_a.clone(); stale_token.fencing_token += 1;
    stale_token.token_ref = identify_delivery_token(&stale_token);
    let stale = request(&c.manifest, q, '6', 101, DeliveryOperation::Acknowledge { token: stale_token });
    let expired = request(&c.manifest, q, '7', 110, DeliveryOperation::Acknowledge { token: token_a.clone() });
    for (label, req, issue) in [("conflicting-duplicate", &conflict, DeliveryIssue::ConflictingDuplicateOperation),
        ("wrong-owner", &wrong, DeliveryIssue::WrongOwner), ("stale-fence", &stale, DeliveryIssue::TokenMismatch),
        ("expired-completion", &expired, DeliveryIssue::LeaseExpired)] {
        let denied = invoke(label, &c, &mut store, &mut timers, &mut statuses, req, output);
        assert_eq!(denied.transition.decision, DeliveryDecisionKind::Denied); assert_eq!(denied.transition.issue, Some(issue));
    }
    let mut expiry = request(&c.manifest, q, '3', 110, DeliveryOperation::ExpireLease { token: token_a.clone() });
    expiry.authority_refs.push(c.policy.expiry_authority_ref.clone());
    let expired = invoke("expiry", &c, &mut store, &mut timers, &mut statuses, &expiry, output);
    assert_eq!(expired.transition.kind, DeliveryTransitionKind::RetryScheduled);
    let mut claim_b = request(&c.manifest, q, '4', 115, DeliveryOperation::Claim); claim_b.actor_id = "consumer-b".into();
    let reclaimed = invoke("claim-b", &c, &mut store, &mut timers, &mut statuses, &claim_b, output);
    let token_b = reclaimed.transition.token.clone().expect("B token"); assert_ne!(token_a.token_ref, token_b.token_ref);
    assert_eq!(token_b.consumer_id, "consumer-b");
    let persisted = store.load(q).expect("load before reopen"); let commits = store.commits; drop(store);
    let mut store = ObservedStore { inner: Local::open(&storage, 13).expect("reopen real Redb"), commits };
    assert_eq!(store.load(q).expect("load reopened"), persisted);
    let duplicate = invoke("reclaimed-a-replay", &c, &mut store, &mut timers, &mut statuses, &claim, output);
    replay_identity(&duplicate, &claimed, None);
    assert!(!molten::preserves_rail::contains_structural_content_ref(&duplicate.receipt.value,
        &reclaimed.transition.operation_ref).expect("no later operation substitution"));
    let old_ack = request(&c.manifest, q, '9', 116, DeliveryOperation::Acknowledge { token: token_a });
    let mut wrong_current = request(&c.manifest, q, 'a', 116, DeliveryOperation::Acknowledge { token: token_b.clone() });
    let mut irrelevant_evidence = wrong_current.clone(); irrelevant_evidence.operation_id = reference('b');
    irrelevant_evidence.evidence_refs.push(claimed.transition.operation_ref.clone());
    for (label, req, issue) in [("old-token-after-reclaim", &old_ack, DeliveryIssue::TokenMismatch),
        ("replay-does-not-authorize", &wrong_current, DeliveryIssue::WrongOwner),
        ("evidence-does-not-authorize", &irrelevant_evidence, DeliveryIssue::WrongOwner)] {
        let denied = invoke(label, &c, &mut store, &mut timers, &mut statuses, req, output);
        assert_eq!(denied.transition.issue, Some(issue)); assert_eq!(denied.transition.decision, DeliveryDecisionKind::Denied);
    }
    wrong_current.operation_id = reference('c'); wrong_current.authority_refs.push(c.policy.completion_authority_ref.clone());
    let completed = invoke("delegated-completion", &c, &mut store, &mut timers, &mut statuses, &wrong_current, output);
    assert_eq!(completed.transition.kind, DeliveryTransitionKind::Acknowledged);
    assert!(completed.transition.next_state.completed.contains_key(&token_b.item_ref));
    for (label, req, original) in [("completed-a-replay", &claim, &claimed), ("completed-b-replay", &claim_b, &reclaimed),
        ("completion-replay", &wrong_current, &completed)] {
        let replay = invoke(label, &c, &mut store, &mut timers, &mut statuses, req, output);
        replay_identity(&replay, original, None);
    }
    let terminal_ack = request(&c.manifest, q, 'd', 117, DeliveryOperation::Acknowledge { token: token_b });
    let denied = invoke("terminal-token-denied", &c, &mut store, &mut timers, &mut statuses, &terminal_ack, output);
    assert_eq!(denied.transition.issue, Some(DeliveryIssue::ItemNotFound));
    let completed_state = store.load(q).expect("completed state"); let commits = store.commits; drop(store);
    let mut store = ObservedStore { inner: Local::open(&storage, 13).expect("completed reopen"), commits };
    assert_eq!(store.load(q).expect("completed reopened"), completed_state);
    let eq = "queue:extension";
    let enq = crate::enqueue(&c.manifest, eq);
    invoke("extension-enqueue", &c, &mut store, &mut timers, &mut statuses, &enq, output);
    let ec = request(&c.manifest, eq, '2', 100, DeliveryOperation::Claim);
    let first = invoke("extension-claim", &c, &mut store, &mut timers, &mut statuses, &ec, output);
    let old = first.transition.token.clone().expect("extension original");
    let extend = request(&c.manifest, eq, '3', 101, DeliveryOperation::ExtendLease { token: old.clone() });
    let extended = invoke("extension", &c, &mut store, &mut timers, &mut statuses, &extend, output);
    let current = extended.transition.token.clone().expect("extended token");
    assert_ne!(old.token_ref, current.token_ref); assert_eq!(current.visibility_deadline_tick, 111);
    let replay = invoke("extended-original-replay", &c, &mut store, &mut timers, &mut statuses, &ec, output);
    replay_identity(&replay, &first, None);
    let replay = invoke("extension-replay", &c, &mut store, &mut timers, &mut statuses, &extend, output);
    replay_identity(&replay, &extended, Some(&current));
    let invalid = request(&c.manifest, eq, '4', 102, DeliveryOperation::Acknowledge { token: old });
    let rejected = invoke("pre-extension-token-denied", &c, &mut store, &mut timers, &mut statuses, &invalid, output);
    assert_eq!(rejected.transition.issue, Some(DeliveryIssue::TokenMismatch));
    let valid = request(&c.manifest, eq, '5', 102, DeliveryOperation::Acknowledge { token: current });
    let accepted = invoke("extended-token-completion", &c, &mut store, &mut timers, &mut statuses, &valid, output);
    assert_eq!(accepted.transition.kind, DeliveryTransitionKind::Acknowledged);
    println!("durable-reopen=pass protected-state-preservation=pass original-token-binding=pass delegated-completion=pass external-effects=not-claimed");
    if args.get(3).is_some_and(|arg| arg == "--expected-deny") {
        eprintln!("expected-deny: real conflict, owner, fence, expired, reclaimed and terminal-token denials observed; no mutation on each rejection");
        std::process::ExitCode::from(1)
    } else { std::process::ExitCode::SUCCESS }
}
